"""
大六壬三传发用模块（九宗门完整版）
功能：贼克、比用、涉害、遥克、昴星、别责、八专、伏吟、返吟
来源：大六壬指南 + 六壬毕法赋 + 大六壬银河棹正附集

九宗门是六壬起三传的核心算法：
1. 贼克法 - 下克上为贼，上克下为克
2. 比用法 - 取与日干比和者为用
3. 涉害法 - 取涉害深者为用
4. 遥克法 - 取遥相克者为用
5. 昴星法 - 阳日取酉上神，阴日取酉下神
6. 别责法 - 取日干合神为初传
7. 八专法 - 干支同位，取干上神
8. 伏吟法 - 天地盘相同
9. 返吟法 - 天地盘对冲
"""

from typing import Dict, List, Optional, Tuple
from .dlr_basic import DLRBasicTools


class SanchuanCalculator:
    """三传计算器（九宗门完整版）"""
    
    ZHI = ["子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥"]
    
    GAN_LU = {
        "甲": "寅", "乙": "卯", "丙": "巳", "丁": "午",
        "戊": "巳", "己": "午", "庚": "申", "辛": "酉",
        "壬": "亥", "癸": "子"
    }
    
    YANG_GAN = ["甲", "丙", "戊", "庚", "壬"]
    YIN_GAN = ["乙", "丁", "己", "辛", "癸"]
    YANG_ZHI = ["子", "寅", "辰", "午", "申", "戌"]
    YIN_ZHI = ["丑", "卯", "巳", "未", "酉", "亥"]
    
    GAN_HE = {
        "甲": "己", "己": "甲",
        "乙": "庚", "庚": "乙",
        "丙": "辛", "辛": "丙",
        "丁": "壬", "壬": "丁",
        "戊": "癸", "癸": "戊"
    }
    
    ZHI_CHONG = {
        "子": "午", "午": "子",
        "丑": "未", "未": "丑",
        "寅": "申", "申": "寅",
        "卯": "酉", "酉": "卯",
        "辰": "戌", "戌": "辰",
        "巳": "亥", "亥": "巳"
    }
    
    ZHI_XING = {
        "寅": "巳", "巳": "申", "申": "寅",
        "丑": "戌", "戌": "未", "未": "丑",
        "子": "卯", "卯": "子",
        "辰": "辰", "午": "午", "酉": "酉", "亥": "亥"
    }
    
    BA_ZHUAN_DAYS = [
        ("甲", "寅"), ("庚", "申"),
        ("丁", "未"), ("己", "未"),
        ("癸", "丑")
    ]
    
    def __init__(self, sike: Dict[str, str], tianpan: List[str], dipan: List[str], day_gan: str, day_zhi: str = None):
        self.sike = sike
        self.tianpan = tianpan
        self.dipan = dipan
        self.day_gan = day_gan
        self.day_zhi = day_zhi or self._get_day_zhi_from_sike()
        self.tools = DLRBasicTools()
        self.keti = ""
    
    def _get_day_zhi_from_sike(self) -> str:
        if 'day_zhi' in self.sike:
            return self.sike['day_zhi']
        return "子"
    
    def get_sanchuan(self) -> Tuple[str, str, str, str]:
        chuanchuan = self._check_fu_fan_yin()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._zeke()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._biyong()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._shehai()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._yaoke()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._maoxing()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._bieze()
        if chuanchuan:
            return chuanchuan
        
        chuanchuan = self._bazhuan()
        if chuanchuan:
            return chuanchuan
        
        return self._default_sanchuan()
    
    def _check_fu_fan_yin(self) -> Optional[Tuple[str, str, str, str]]:
        is_fuyin = self.tianpan == self.dipan
        is_fanyin = all(self.ZHI_CHONG.get(self.tianpan[i], "") == self.dipan[i] 
                       for i in range(len(self.tianpan)))
        
        if is_fuyin:
            return self._fuyin()
        
        if is_fanyin:
            return self._fanyin()
        
        return None
    
    def _get_shang_shen(self, base_shen: str) -> str:
        if base_shen not in self.dipan:
            return "未知"
        index = self.dipan.index(base_shen)
        return self.tianpan[index]
    
    def _get_xia_shen(self, tian_shen: str) -> str:
        if tian_shen not in self.tianpan:
            return "未知"
        index = self.tianpan.index(tian_shen)
        return self.dipan[index]
    
    def _is_yang_gan(self) -> bool:
        return self.day_gan in self.YANG_GAN
    
    def _is_yang_zhi(self, zhi: str) -> bool:
        return zhi in self.YANG_ZHI
    
    def _get_ke_relations(self) -> Tuple[List[Dict], List[Dict]]:
        zei_list = []
        ke_list = []
        
        lessons = [
            {'name': '一课', 'lower': self.sike.get('gan_lu', ''), 'upper': self.sike.get('gan_shang', '')},
            {'name': '二课', 'lower': self.sike.get('gan_shang', ''), 'upper': self.sike.get('gan_yin', '')},
            {'name': '三课', 'lower': self.day_zhi, 'upper': self.sike.get('zhi_shang', '')},
            {'name': '四课', 'lower': self.sike.get('zhi_shang', ''), 'upper': self.sike.get('zhi_yin', '')}
        ]
        
        for lesson in lessons:
            lower = lesson['lower']
            upper = lesson['upper']
            
            if not lower or not upper:
                continue
            
            lower_wx = self.tools.get_zhi_wuxing(lower)
            upper_wx = self.tools.get_zhi_wuxing(upper)
            
            if self.tools.is_ke(lower_wx, upper_wx):
                zei_list.append({
                    'lesson': lesson['name'],
                    'lower': lower,
                    'upper': upper,
                    'type': '贼'
                })
            
            if self.tools.is_ke(upper_wx, lower_wx):
                ke_list.append({
                    'lesson': lesson['name'],
                    'lower': lower,
                    'upper': upper,
                    'type': '克'
                })
        
        return zei_list, ke_list
    
    def _zeke(self) -> Optional[Tuple[str, str, str, str]]:
        zei_list, ke_list = self._get_ke_relations()
        
        if len(zei_list) == 1:
            self.keti = "重审"
            chuanchuan = zei_list[0]['upper']
            zhongchuan = self._get_shang_shen(chuanchuan)
            mochuan = self._get_shang_shen(zhongchuan)
            return (chuanchuan, zhongchuan, mochuan, self.keti)
        
        if len(zei_list) == 0 and len(ke_list) == 1:
            self.keti = "元首"
            chuanchuan = ke_list[0]['upper']
            zhongchuan = self._get_shang_shen(chuanchuan)
            mochuan = self._get_shang_shen(zhongchuan)
            return (chuanchuan, zhongchuan, mochuan, self.keti)
        
        return None
    
    def _biyong(self) -> Optional[Tuple[str, str, str, str]]:
        zei_list, ke_list = self._get_ke_relations()
        
        candidates = []
        
        if len(zei_list) > 1:
            for item in zei_list:
                upper = item['upper']
                if self._is_same_yinyang(upper):
                    candidates.append(upper)
            
            if candidates:
                self.keti = "比用"
                chuanchuan = candidates[0]
                zhongchuan = self._get_shang_shen(chuanchuan)
                mochuan = self._get_shang_shen(zhongchuan)
                return (chuanchuan, zhongchuan, mochuan, self.keti)
        
        if len(ke_list) > 1:
            for item in ke_list:
                upper = item['upper']
                if self._is_same_yinyang(upper):
                    candidates.append(upper)
            
            if candidates:
                self.keti = "知一"
                chuanchuan = candidates[0]
                zhongchuan = self._get_shang_shen(chuanchuan)
                mochuan = self._get_shang_shen(zhongchuan)
                return (chuanchuan, zhongchuan, mochuan, self.keti)
        
        return None
    
    def _is_same_yinyang(self, zhi: str) -> bool:
        is_yang_gan = self._is_yang_gan()
        is_yang_zhi = self._is_yang_zhi(zhi)
